    # Defensive defaults
    x = observation.get("agent_x", 0)
    y = observation.get("agent_y", 0)
    # Prefer staying in place if no clear objective
    dx = 0
    dy = 0

    # Helpers to access safely
    grid = observation.get("grid", [])
    width = observation.get("width", len(grid[0]) if grid else 0)
    height = observation.get("height", len(grid) if grid else 0)

    # Resource collection: move toward nearest resource if present
    resources = observation.get("resources", [])
    if resources:
        # find closest resource
        best = None
