            if ox > x:
                dx = -1
            elif ox < x:
                dx = 1
            if oy > y:
                dy = -1
            elif oy < y:
                dy = 1
            return [dx, dy]

    # Territory control: avoid borders or stay near center if no other info
    # Try to move toward center (assumed best hold)
    center_x = width // 2
    center_y = height // 2
    if width and height:
